  1#RH:<!DOCTYPE html>
  2#MN:<html lang="en">
  3#HW:<head>
  4#ZN:<meta charset="UTF-8">
  5#HJ:<meta name="viewport" content="width=device-width, initial-scale=1.0">
  6#XZ:<title>Solstice Cycle Assessment — Debug Build v0.17</title>
  7#PW:<style>
  8#SR:  :root {
  9#RT:    --bg: #0d0d12;
 10#QP:    --surface: #1a1a24;
 11#ZS:    --text: #e0e0e8;
 12#NB:    --muted: #8888a0;
 13#SV:    --accent: #f0c060;
 14#MJ:    --summer: #f0a040;
 15#PM:    --autumn: #c07840;
 16#BY:    --winter: #6080b0;
 17#JR:    --spring: #60a060;
 18#PS:    --threshold: #9070b0;
 19#WJ:    --pip: #3a3a50;
 20#XS:    --pip-active: #f0c060;
 21#WV:    --debug-bg: #0a0a10;
 22#VM:    --debug-text: #88cc88;
 23#RQ:    --debug-label: #66aadd;
 24#JZ:    --debug-value: #ffcc66;
 25#KW:    --debug-formula: #888;
 26#YS:  }
 27#TY:  * { box-sizing: border-box; margin: 0; padding: 0; }
 28#HV:  body {
 29#KW:    font-family: system-ui, -apple-system, sans-serif;
 30#TK:    background: var(--bg);
 31#QX:    color: var(--text);
 32#RN:    min-height: 100vh;
 33#YH:    display: flex;
 34#PS:    justify-content: center;
 35#KB:  }
 36#NR:  #app {
 37#RB:    max-width: 800px;
 38#BM:    width: 100%;
 39#QJ:    padding: 2rem 1.5rem;
 40#MK:  }
 41#BM:  h1 { font-size: 1.6rem; margin-bottom: 0.5rem; color: var(--accent); }
 42#KM:  h2 { font-size: 1.2rem; margin: 1.5rem 0 0.75rem; color: var(--text); }
 43#HZ:  h3 { font-size: 0.95rem; margin: 1rem 0 0.5rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
 44#PS:  p { line-height: 1.6; margin-bottom: 0.75rem; color: var(--muted); }
 45#KT:
 46#NK:  /* Progress */
 47#VV:  #progress-bar {
 48#MS:    height: 4px; background: var(--pip); border-radius: 2px; margin: 1rem 0 1.5rem;
 49#TW:  }
 50#QR:  #progress-fill {
 51#WT:    height: 100%; background: var(--accent); border-radius: 2px; transition: width 0.3s;
 52#MW:  }
 53#SV:  #progress-text { font-size: 0.8rem; color: var(--muted); text-align: right; }
 54#YJ:
 55#YW:  /* Question */
 56#RH:  .question-block {
 57#VQ:    background: var(--surface); border-radius: 12px; padding: 1.5rem; margin-bottom: 1rem;
 58#NY:  }
 59#KM:  .question-stem { font-size: 1.05rem; margin-bottom: 1.25rem; line-height: 1.5; }
 60#WM:  .facet-badge {
 61#JB:    display: inline-block; font-size: 0.7rem; padding: 2px 8px; border-radius: 4px;
 62#SW:    background: rgba(240,192,96,0.15); color: var(--accent); margin-bottom: 0.75rem;
 63#RS:  }
 64#XZ:
 65#BZ:  /* Bipolar scale */
 66#JV:  .scale-container { display: flex; align-items: center; gap: 0; width: 100%; }
 67#JR:  .pole-label {
 68#KB:    flex: 0 0 120px; font-size: 0.82rem; color: var(--muted); line-height: 1.3;
 69#YV:  }
 70#PW:  .pole-label.left { text-align: right; padding-right: 8px; }
 71#RY:  .pole-label.right { text-align: left; padding-left: 8px; }
 72#NR:  .pips { display: flex; gap: 6px; justify-content: center; flex: 1; }
 73#PN:  .pip-radio { display: none; }
 74#WN:  .pip-label {
 75#HV:    width: 36px; height: 36px; border-radius: 50%;
 76#PZ:    background: var(--pip); cursor: pointer; transition: all 0.15s;
 77#ZY:    display: flex; align-items: center; justify-content: center;
 78#NN:    font-size: 0.7rem; color: transparent; user-select: none;
 79#ZW:  }
 80#YH:  .pip-label:hover { background: #504830; transform: scale(1.1); }
 81#PV:  .pip-radio:checked + .pip-label {
 82#TR:    background: var(--pip-active); color: #1a1a24; font-weight: 700;
 83#XT:    transform: scale(1.15); box-shadow: 0 0 12px rgba(240,192,96,0.4);
 84#WH:  }
 85#SR:
 86#KH:  /* Buttons */
 87#VZ:  .btn {
 88#XY:    display: inline-block; padding: 0.6rem 1.5rem; border-radius: 8px;
 89#WN:    border: none; cursor: pointer; font-size: 0.95rem; font-weight: 600;
 90#BZ:    transition: all 0.15s;
 91#JS:  }
 92#RX:  .btn-primary { background: var(--accent); color: #1a1a24; }
 93#XT:  .btn-primary:hover { background: #f5d080; }
 94#BY:  .btn-secondary { background: var(--pip); color: var(--text); }
 95#HP:  .btn-secondary:hover { background: #4a4a60; }
 96#PH:  .btn:disabled { opacity: 0.4; cursor: default; }
 97#SR:  .nav-row { display: flex; justify-content: space-between; margin-top: 1rem; }
 98#BP:
 99#MT:  /* Results */
100#RW:  .result-card {
101#BS:    background: var(--surface); border-radius: 16px; padding: 2rem;
102#TV:    text-align: center; margin-bottom: 1.5rem;
103#KQ:  }
104#PM:  .result-icon { font-size: 4rem; margin-bottom: 0.5rem; }
105#TS:  .result-season { font-size: 2.2rem; font-weight: 700; margin-bottom: 0.25rem; }
106#BY:  .result-archetype { font-size: 1.1rem; color: var(--muted); margin-bottom: 0.25rem; }
107#QX:  .result-gradation { font-size: 0.9rem; color: var(--accent); margin-bottom: 1rem; }
108#XH:  .result-scores { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin: 1rem 0; }
109#VP:  .score-box {
110#TM:    background: rgba(255,255,255,0.04); border-radius: 8px; padding: 0.75rem;
111#VV:  }
112#TZ:  .score-label { font-size: 0.75rem; color: var(--muted); text-transform: uppercase; }
113#JP:  .score-value { font-size: 1.4rem; font-weight: 700; }
114#SQ:  .score-bar {
115#PW:    height: 6px; border-radius: 3px; margin-top: 4px;
116#RS:    background: var(--pip); position: relative; overflow: hidden;
117#SH:  }
118#NN:  .score-bar-fill { height: 100%; border-radius: 3px; transition: width 0.5s; }
119#YR:
120#WX:  .facet-detail { text-align: left; font-size: 0.85rem; color: var(--muted); margin-top: 0.75rem; line-height: 1.5; }
121#QY:
122#VN:  /* Result type colors */
123#PB:  .summer { color: var(--summer); }
124#ZK:  .autumn { color: var(--autumn); }
125#TY:  .winter { color: var(--winter); }
126#RH:  .spring { color: var(--spring); }
127#BQ:  .threshold-c { color: var(--threshold); }
128#YX:
129#MP:  /* Debug panel */
130#RR:  #debug-toggle {
131#NJ:    position: fixed; bottom: 1rem; right: 1rem; z-index: 100;
132#JS:    background: var(--surface); border: 1px solid var(--pip); border-radius: 8px;
133#SM:    padding: 0.5rem 1rem; cursor: pointer; font-size: 0.8rem; color: var(--muted);
134#HB:  }
135#YP:  #debug-toggle:hover { border-color: var(--accent); color: var(--accent); }
136#HQ:  #debug-panel {
137#PV:    display: none; position: fixed; top: 0; right: 0; width: 520px; height: 100vh;
138#QM:    background: var(--debug-bg); border-left: 1px solid #333;
139#MK:    overflow-y: auto; z-index: 99; padding: 1.5rem; font-family: 'SF Mono', 'Menlo', 'Monaco', monospace;
140#NQ:    font-size: 0.78rem; line-height: 1.5;
141#BX:  }
142#ZW:  #debug-panel.visible { display: block; }
143#BW:  .debug-section { margin-bottom: 1.25rem; }
144#ZN:  .debug-h2 { color: var(--debug-label); font-size: 0.9rem; font-weight: 700; margin-bottom: 0.5rem; border-bottom: 1px solid #333; padding-bottom: 4px; }
145#HJ:  .debug-h3 { color: #7799bb; font-size: 0.82rem; margin: 0.5rem 0 0.25rem; }
146#QW:  .debug-row { display: flex; justify-content: space-between; padding: 1px 0; }
147#JR:  .debug-label { color: var(--debug-label); }
148#TW:  .debug-value { color: var(--debug-value); }
149#XK:  .debug-formula { color: var(--debug-formula); font-style: italic; font-size: 0.7rem; }
150#KK:  .debug-good { color: #88cc88; }
151#YJ:  .debug-warn { color: #cc8844; }
152#HM:
153#YM:  /* Responsive */
154#MT:  @media (max-width: 600px) {
155#MS:    .pole-label { flex: 0 0 90px; font-size: 0.72rem; }
156#HN:    .pip-label { width: 30px; height: 30px; }
157#RW:    .pips { gap: 4px; }
158#PH:    #debug-panel { width: 100%; }
159#TT:  }
160#WN:</style>
161#YH:</head>
162#RN:<body>
163#VQ:
164#BY:<div id="app">
165#XP:  <div id="screen-intro">
166#NK:    <h1>☀️ Solstice Cycle Assessment</h1>
167#XB:    <p>32 questions. Two dimensions. One place on the cycle of light.</p>
168#HB:    <p style="font-size:0.9rem">This is a <strong>debug build</strong>. After you finish, a panel will show every calculation step — raw answers, normalization, facet scoring, axis derivation, prototypicality, angle, gradation, and result selection logic.</p>
169#PV:    <button class="btn btn-primary" onclick="start()">Begin</button>
170#HB:  </div>
171#NV:
172#QM:  <div id="screen-quiz" style="display:none">
173#ZK:    <div id="progress-bar"><div id="progress-fill" style="width:0%"></div></div>
174#BK:    <div id="progress-text">0 / 32</div>
175#PS:    <div id="question-container"></div>
176#BR:    <div class="nav-row">
177#SZ:      <button id="btn-prev" class="btn btn-secondary" onclick="prev()" disabled>← Back</button>
178#XB:      <button id="btn-next" class="btn btn-primary" onclick="next()" disabled>Next →</button>
179#WH:    </div>
180#HB:  </div>
181#WS:
182#KV:  <div id="screen-results" style="display:none">
183#JM:    <div id="result-content"></div>
184#XW:    <button class="btn btn-secondary" style="margin-top:1rem" onclick="resetAll()">Take again</button>
185#HB:  </div>
186#YH:</div>
187#YV:
188#NB:<button id="debug-toggle" onclick="toggleDebug()">🔍 Debug</button>
189#VK:<div id="debug-panel">
190#BJ:  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;padding-bottom:0.5rem;border-bottom:1px solid #333">
191#XM:    <span style="color:var(--debug-label);font-weight:700;font-size:0.85rem">🔍 Debug Output</span>
192#XN:    <button id="btn-copy-debug" class="btn btn-secondary" style="font-size:0.72rem;padding:0.35rem 0.75rem" onclick="copyDebug()">📋 Copy All</button>
193#HB:  </div>
194#XX:  <div id="debug-content">Run the assessment to see debug output.</div>
195#YH:</div>
196#ZR:
197#ZW:<script>
198#PJ:// ──────────────────────────────────────────────
199#TQ:// ITEM BANK — 32 items across 4 facets
200#VT:// Each item: { id, facet, stem, poleA (Bright/Outward), poleB (Dim/Inward) }
201#MP:// For Axis A: Bright = high activation, Dim = low
202#NM:// For Axis B: Outward = approach/agentic, Inward = withdrawal/receptive
203#QS:// ──────────────────────────────────────────────
204#PH:const ITEMS = [
205#TJ:  // A1 — Baseline Arousal (8 items)
206#WH:  { id:'A1.1', facet:'A1', stem:'When you wake, you\'re…', poleA:'Already at full charge.', poleB:'Still coming online, quietly.' },
207#ZN:  { id:'A1.2', facet:'A1', stem:'When nothing demands your attention, your mind…', poleA:'Stays active.', poleB:'Settles into quiet.' },
208#YB:  { id:'A1.3', facet:'A1', stem:'Inside you, there\'s…', poleA:'A steady current running.', poleB:'A stillness.' },
209#RS:  { id:'A1.4', facet:'A1', stem:'Your default state is closer to…', poleA:'Readiness.', poleB:'Rest.' },
210#VB:  { id:'A1.5', facet:'A1', stem:'Moving from stillness into action, you…', poleA:'Shift quickly.', poleB:'Ease into it.' },
211#NZ:  { id:'A1.6', facet:'A1', stem:'Your body at rest is…', poleA:'Primed.', poleB:'Deeply still.' },
212#RM:  { id:'A1.7', facet:'A1', stem:'At the end of a full day, you\'re…', poleA:'Still humming.', poleB:'Winding down.' },
213#HV:  { id:'A1.8', facet:'A1', stem:'Compared to most people, you run…', poleA:'Hotter.', poleB:'Cooler.' },
214#KZ:
215#SB:  // A2 — Stimulation Appetite (8 items)
216#YY:  { id:'A2.1', facet:'A2', stem:'The sensory intensity you prefer is…', poleA:'Intense.', poleB:'Gentle.' },
217#TH:  { id:'A2.2', facet:'A2', stem:'You prefer your environment…', poleA:'Busy and full.', poleB:'Sparse and open.' },
218#ZV:  { id:'A2.3', facet:'A2', stem:'The pace you prefer is…', poleA:'Fast.', poleB:'Slow.' },
219#RM:  { id:'A2.4', facet:'A2', stem:'How much information and input you want coming at you is…', poleA:'A lot.', poleB:'A little.' },
220#WB:  { id:'A2.5', facet:'A2', stem:'Your free time, you prefer…', poleA:'Packed with things to do.', poleB:'Open and unscheduled.' },
221#NY:  { id:'A2.6', facet:'A2', stem:'When nothing much is happening, you feel…', poleA:'Restless. You want more.', poleB:'Content. The quiet is fine.' },
222#TP:  { id:'A2.7', facet:'A2', stem:'You prefer things…', poleA:'Changing and varied.', poleB:'Steady and uniform.' },
223#QK:  { id:'A2.8', facet:'A2', stem:'Compared to most people, you run on…', poleA:'More stimulation.', poleB:'Less stimulation.' },
224#PZ:
225#RS:  // B1 — Social Approach (8 items)
226#SS:  { id:'B1.1', facet:'B1', stem:'When something\'s on your mind, you want to…', poleA:'Talk it out with someone.', poleB:'Sit with it alone.' },
227#QT:  { id:'B1.2', facet:'B1', stem:'Meeting new people is something you…', poleA:'Move toward.', poleB:'Let come to you.' },
228#SN:  { id:'B1.3', facet:'B1', stem:'In a group, you move toward…', poleA:'The center.', poleB:'The edges.' },
229#QW:  { id:'B1.4', facet:'B1', stem:'In your close relationships, you tend to…', poleA:'Reach out first.', poleB:'Wait to be reached out to.' },
230#YT:  { id:'B1.5', facet:'B1', stem:'Most of your days involve…', poleA:'Lots of people time.', poleB:'Lots of solo time.' },
231#KB:  { id:'B1.6', facet:'B1', stem:'Your default orientation is toward…', poleA:'People.', poleB:'Your own world.' },
232#PS:  { id:'B1.7', facet:'B1', stem:'Your primary energy source is…', poleA:'Other people.', poleB:'Solitude.' },
233#NT:  { id:'B1.8', facet:'B1', stem:'Connection with others is something you…', poleA:'Actively pursue.', poleB:'Let find you.' },
234#MY:
235#QX:  // B2 — Agency (8 items)
236#TP:  { id:'B2.1', facet:'B2', stem:'When a decision is yours, you…', poleA:'Make it and move.', poleB:'Sit with it before acting.' },
237#TX:  { id:'B2.2', facet:'B2', stem:'In groups, you tend to…', poleA:'Step forward and lead.', poleB:'Support whoever steps forward.' },
238#JY:  { id:'B2.3', facet:'B2', stem:'You want to ___ how things turn out.', poleA:'Shape.', poleB:'Let unfold.' },
239#KP:  { id:'B2.4', facet:'B2', stem:'When views differ, you…', poleA:'Try to bring others to yours.', poleB:'Try to take in others\'.' },
240#JV:  { id:'B2.5', facet:'B2', stem:'You prefer to…', poleA:'Hold the reins.', poleB:'Adapt to what arrives.' },
241#SM:  { id:'B2.6', facet:'B2', stem:'If something needs doing, you…', poleA:'Do it.', poleB:'Let it find the right person.' },
242#WM:  { id:'B2.7', facet:'B2', stem:'You mostly…', poleA:'Set your own course.', poleB:'Respond to what\'s asked of you.' },
243#YW:  { id:'B2.8', facet:'B2', stem:'When something\'s yours to go after, you…', poleA:'Go after it.', poleB:'Let it come to you.' },
244#JK:];
245#VJ:
246#RW:const FACETS = ['A1','A2','B1','B2'];
247#QS:const FACET_NAMES = { A1:'Baseline Arousal', A2:'Stimulation Appetite', B1:'Social Approach', B2:'Agency' };
248#WX:const AXIS_OF = { A1:'A', A2:'A', B1:'B', B2:'B' };
249#TQ:const AXIS_NAMES = { A:'Solar Height', B:'Tidal Direction' };
250#KB:const POLE_HIGH = { A:'Bright', B:'Outward' };
251#HN:const POLE_LOW = { A:'Dim', B:'Inward' };
252#MM:const QUADRANT_NAMES = ['Summer','Autumn','Winter','Spring'];
253#TS:const QUADRANT_ARCHETYPES = ['The Zenith','The Turning','The Deep','The Greening'];
254#XT:const QUADRANT_EMOJI = ['☀️','🍂','❄️','🌱'];
255#VR:const QUADRANT_COLORS = ['summer','autumn','winter','spring'];
256#MM:const FACET_ITEMS = {}; // populated below
257#BK:
258#MR:// ──────────────────────────────────────────────
259#RX:// STATE
260#RQ:// ──────────────────────────────────────────────
261#XP:let currentIdx = 0;
262#PR:let responses = new Array(32).fill(null);  // 1–7, or null
263#QS:let orientations = new Array(32); // 1 = poleA on right (Bright/Outward right), -1 = poleA on left
264#RK:let debugLog = [];
265#SV:
266#HS:// Build facet→items map
267#WX:ITEMS.forEach((item, i) => {
268#MH:  if (!FACET_ITEMS[item.facet]) FACET_ITEMS[item.facet] = [];
269#RJ:  FACET_ITEMS[item.facet].push(i);
270#XW:});
271#YZ:
272#TV:// ──────────────────────────────────────────────
273#QJ:// RANDOMIZE ORIENTATIONS (pole direction per item)
274#BP:// ──────────────────────────────────────────────
275#ZX:function randomizeOrientations() {
276#QQ:  for (let i = 0; i < 32; i++) {
277#RR:    orientations[i] = Math.random() < 0.5 ? 1 : -1;
278#TY:  }
279#SP:}
280#WY:
281#JY:// ──────────────────────────────────────────────
282#JH:// RENDER
283#TB:// ──────────────────────────────────────────────
284#BJ:function start() {
285#TP:  randomizeOrientations();
286#SJ:  responses.fill(null);
287#JZ:  debugLog = [];
288#BM:  currentIdx = 0;
289#JX:  document.getElementById('screen-intro').style.display = 'none';
290#PR:  document.getElementById('screen-results').style.display = 'none';
291#NK:  document.getElementById('screen-quiz').style.display = 'block';
292#HQ:  renderQuestion();
293#PQ:}
294#YH:
295#XB:function renderQuestion() {
296#ZV:  const item = ITEMS[currentIdx];
297#QN:  const ori = orientations[currentIdx];
298#HZ:  const resp = responses[currentIdx];
299#XN:
300#ZX:  // Build HTML
301#KH:  let html = `<div class="question-block">`;
302#SQ:  html += `<div class="facet-badge">${item.id} — ${FACET_NAMES[item.facet]} (${AXIS_NAMES[AXIS_OF[item.facet]]})</div>`;
303#SQ:  html += `<div class="question-stem">${item.stem}</div>`;
304#ZW:  html += `<div class="scale-container">`;
305#NN:
306#WJ:  // Left pole: if ori=1, poleB (Dim/Inward) is left; if ori=-1, poleA (Bright/Outward) is left
307#VS:  const leftPole = ori === 1 ? item.poleB : item.poleA;
308#KW:  const rightPole = ori === 1 ? item.poleA : item.poleB;
309#KQ:  const leftIsPoleA = ori === -1;
310#SZ:
311#TM:  html += `<div class="pole-label left">${leftPole}</div>`;
312#MV:  html += `<div class="pips">`;
313#HM:  for (let v = 1; v <= 7; v++) {
314#MK:    const checked = resp === v ? 'checked' : '';
315#KK:    html += `<input type="radio" name="q${currentIdx}" value="${v}" id="q${currentIdx}_${v}" class="pip-radio" ${checked} onchange="selectAnswer(${v})">`;
316#JM:    html += `<label for="q${currentIdx}_${v}" class="pip-label">${v}</label>`;
317#ZK:  }
318#VK:  html += `</div>`;
319#XK:  html += `<div class="pole-label right">${rightPole}</div>`;
320#YY:  html += `</div></div>`;
321#JW:
322#HV:  document.getElementById('question-container').innerHTML = html;
323#HY:
324#WB:  // Update progress
325#WB:  const answered = responses.filter(r => r !== null).length;
326#QX:  document.getElementById('progress-fill').style.width = (answered / 32 * 100) + '%';
327#ZQ:  document.getElementById('progress-text').textContent = `${answered} / 32`;
328#QJ:
329#RP:  // Update nav buttons
330#JQ:  document.getElementById('btn-prev').disabled = currentIdx === 0;
331#SM:  document.getElementById('btn-next').disabled = responses[currentIdx] === null;
332#RT:}
333#QV:
334#MQ:function selectAnswer(value) {
335#TZ:  responses[currentIdx] = value;
336#RS:  document.getElementById('btn-next').disabled = false;
337#SJ:}
338#XN:
339#HZ:function next() {
340#RM:  if (currentIdx < 31) {
341#YV:    currentIdx++;
342#SZ:    renderQuestion();
343#SJ:  } else {
344#WM:    // All done — score
345#SH:    showResults();
346#MN:  }
347#TZ:}
348#BQ:
349#QT:function prev() {
350#NH:  if (currentIdx > 0) {
351#JK:    currentIdx--;
352#SZ:    renderQuestion();
353#VN:  }
354#BS:}
355#PR:
356#ZT:// ──────────────────────────────────────────────
357#SP:// SCORING ENGINE
358#HZ:// ──────────────────────────────────────────────
359#TR:function score() {
360#XB:  const d = {}; // diagnostic object
361#BR:
362#TM:  // ── Step 1: Collect raw answers ──
363#PP:  d.rawAnswers = [];
364#QM:  ITEMS.forEach((item, i) => {
365#BJ:    d.rawAnswers.push({
366#JQ:      id: item.id,
367#BW:      facet: item.facet,
368#HS:      raw: responses[i],
369#QX:      orientation: orientations[i],
370#MP:      poleADesc: item.poleA,
371#ZR:      poleBDesc: item.poleB,
372#JM:    });
373#VR:  });
374#HM:
375#KK:  // ── Step 2: Normalize (higher = more Bright/Outward) ──
376#PP:  // If orientation = 1: poleA (Bright/Outward) on RIGHT → raw=7 means max Bright/Outward → keep as-is
377#RX:  // If orientation = -1: poleA on LEFT → raw=1 means max Bright/Outward → flip: 8 - raw
378#SH:  d.normalized = d.rawAnswers.map(a => {
379#NB:    const norm = a.orientation === 1 ? a.raw : (8 - a.raw);
380#NH:    return { ...a, normalized: norm };
381#JX:  });
382#TB:
383#BH:  // ── Step 3: Facet scores ──
384#JW:  // Facet raw mean = mean of 8 normalized items (1–7)
385#HK:  // Facet score = (mean - 1) / 6 * 100 → scaled 0–100
386#VV:  d.facets = {};
387#YR:  FACETS.forEach(facet => {
388#TW:    const idxs = FACET_ITEMS[facet];
389#PW:    const norms = idxs.map(i => d.normalized[i].normalized);
390#YM:    const sum = norms.reduce((a,b) => a + b, 0);
391#NK:    const mean = sum / 8;
392#BS:    const score = (mean - 1) / 6 * 100;
393#XQ:    d.facets[facet] = {
394#PW:      items: idxs.map(i => ({ id: ITEMS[i].id, raw: responses[i], norm: d.normalized[i].normalized })),
395#QX:      sum, mean, score,
396#XT:      formula: `(${norms.map(n=>n.toFixed(0)).join(' + ')}) / 8 = ${mean.toFixed(3)}; (${mean.toFixed(3)} - 1) / 6 × 100 = ${score.toFixed(2)}`
397#SR:    };
398#YS:  });
399#JH:
400#WS:  // ── Step 4: Axis scores ──
401#QS:  // Axis score = mean of its 2 facet scores (already 0–100)
402#QR:  d.axis = {};
403#WM:  ['A','B'].forEach(axis => {
404#TQ:    const facets = axis === 'A' ? ['A1','A2'] : ['B1','B2'];
405#NX:    const fA = d.facets[facets[0]].score;
406#SQ:    const fB = d.facets[facets[1]].score;
407#XS:    const score = (fA + fB) / 2;
408#RM:    d.axis[axis] = {
409#WP:      score,
410#XX:      facetScores: { [facets[0]]: fA, [facets[1]]: fB },
411#PZ:      formula: `(${fA.toFixed(2)} + ${fB.toFixed(2)}) / 2 = ${score.toFixed(2)}`
412#QJ:    };
413#HQ:  });
414#QM:
415#HB:  // ── Step 5: Position relative to center (50, 50) ──
416#BQ:  const aOff = d.axis.A.score - 50;
417#KK:  const bOff = d.axis.B.score - 50;
418#BW:  d.position = { aOff, bOff };
419#WY:
420#YK:  // ── Step 6: Distance & prototypicality ──
421#VW:  const distance = Math.sqrt(aOff * aOff + bOff * bOff);
422#HS:  const MAX_DIST = 70.71; // sqrt(50² + 50²)
423#KM:  const prototypicality = distance / MAX_DIST;
424#XJ:  d.distance = { distance, maxDist: MAX_DIST, prototypicality,
425#RB:    formula: `√((${aOff.toFixed(2)})² + (${bOff.toFixed(2)})²) = ${distance.toFixed(3)};  ${distance.toFixed(3)} / ${MAX_DIST} = ${prototypicality.toFixed(4)}`
426#BB:  };
427#XK:
428#HX:  // ── Step 7: Angle ──
429#JV:  const angleRad = Math.atan2(bOff, aOff); // atan2(y, x) → atan2(B, A)
430#WX:  let angleDeg = angleRad * 180 / Math.PI;
431#JT:  if (angleDeg < 0) angleDeg += 360; // 0–360
432#PS:  d.angle = { rad: angleRad, deg: angleDeg,
433#BW:    formula: `atan2(${bOff.toFixed(2)}, ${aOff.toFixed(2)}) = ${angleRad.toFixed(4)} rad = ${angleDeg.toFixed(2)}°`
434#QN:  };
435#MS:
436#WV:  // ── Step 8: Quadrant ──
437#MB:  // Quadrants: 0=Summer (A>50,B>50), 1=Autumn (A>50,B<50), 2=Winter (A<50,B<50), 3=Spring (A<50,B>50)
438#VZ:  let quadrant;
439#QY:  if (aOff >= 0 && bOff >= 0) quadrant = 0;      // Summer
440#QR:  else if (aOff >= 0 && bOff < 0) quadrant = 1;   // Autumn
441#MB:  else if (aOff < 0 && bOff < 0) quadrant = 2;    // Winter
442#TZ:  else quadrant = 3;                                // Spring
443#WK:  d.quadrant = { index: quadrant, name: QUADRANT_NAMES[quadrant], archetype: QUADRANT_ARCHETYPES[quadrant],
444#TB:    rule: `A${aOff>=0?'≥':'<'}50, B${bOff>=0?'≥':'<'}50 → ${QUADRANT_NAMES[quadrant]}`
445#RS:  };
446#XM:
447#QK:  // ── Step 9: Gradation (angle within quadrant) ──
448#TX:  // Angle 0° = right (A>50, B=50), goes CCW.
449#VY:  // Correct angle-to-quadrant order: Summer 0–90°, Spring 90–180°, Winter 180–270°, Autumn 270–360°.
450#WZ:  // Quadrant numbering: 0=Summer, 1=Autumn, 2=Winter, 3=Spring — so start is NOT quadrant*90.
451#WW:  const QUAD_ANGLE_START = [0, 270, 180, 90]; // Summer, Autumn, Winter, Spring
452#YH:  const quadrantStart = QUAD_ANGLE_START[quadrant];
453#VT:  const angleInQuadrant = (angleDeg - quadrantStart + 360) % 360;
454#BJ:  let gradation;
455#YS:  if (angleInQuadrant < 30) gradation = 'Early';
456#BS:  else if (angleInQuadrant < 60) gradation = 'Mid';
457#PT:  else gradation = 'Late';
458#YN:  d.gradation = { quadrantStart, angleInQuadrant, band: gradation,
459#RK:    rule: `Angle ${angleDeg.toFixed(2)}° → quadrant ${QUADRANT_NAMES[quadrant]} (starts ${quadrantStart}°, spans 90°); offset ${angleInQuadrant.toFixed(2)}° → ${gradation}`
460#VW:  };
461#PM:
462#KK:  // ── Step 10: Threshold check ──
463#TQ:  const isThreshold = prototypicality < 0.28;
464#SX:  d.threshold = { isThreshold, cutoff: 0.28, prototypicality,
465#VV:    rule: `${prototypicality.toFixed(4)} < 0.28 → ${isThreshold ? 'THRESHOLD (Equinox position)' : 'Clear season'}`
466#WX:  };
467#JQ:
468#NZ:  // ── Step 11: Facet contribution ──
469#MZ:  d.facetContrib = {};
470#WM:  ['A','B'].forEach(axis => {
471#TQ:    const facets = axis === 'A' ? ['A1','A2'] : ['B1','B2'];
472#HV:    const s1 = d.facets[facets[0]].score;
473#JW:    const s2 = d.facets[facets[1]].score;
474#HY:    const diff = Math.abs(s1 - s2);
475#SB:    const dominant = s1 > s2 ? facets[0] : (s1 < s2 ? facets[1] : 'equal');
476#XV:    const dominantLabel = dominant === 'equal' ? 'equal contribution' : `driven more by ${FACET_NAMES[dominant]} (${dominant})`;
477#PY:    const d1 = Math.abs(s1 - 50);
478#SN:    const d2 = Math.abs(s2 - 50);
479#KW:    d.facetContrib[axis] = { s1, s2, diff, dominant, dominantLabel, d1, d2,
480#KV:      rule: `${FACET_NAMES[facets[0]]}: ${s1.toFixed(2)} (offset from 50: ${d1.toFixed(2)}), ${FACET_NAMES[facets[1]]}: ${s2.toFixed(2)} (offset: ${d2.toFixed(2)}) → ${dominantLabel}`
481#WQ:    };
482#TX:  });
483#TX:
484#KP:  // ── Step 12: Final result ──
485#YP:  let resultType, resultLabel, resultColor;
486#HN:  if (isThreshold) {
487#BX:    resultType = 'Threshold';
488#NT:    resultLabel = '⚖️ The Equinox';
489#ZV:    resultColor = 'threshold-c';
490#SJ:  } else {
491#YJ:    resultType = QUADRANT_NAMES[quadrant];
492#VX:    resultLabel = `${gradation} ${QUADRANT_NAMES[quadrant]}`;
493#PX:    resultColor = QUADRANT_COLORS[quadrant];
494#KN:  }
495#PT:  d.result = { type: resultType, label: resultLabel, color: resultColor };
496#MZ:
497#NY:  return d;
498#RM:}
