103#MB:const FACETS: FacetId[] = ["A1", "A2", "B1", "B2"];
104#RB:const FACET_NAMES: Record<FacetId, string> = {
105#YS:  A1: "Baseline Arousal", A2: "Stimulation Appetite",
106#HS:  B1: "Social Approach", B2: "Agency",
107#WY:};
108#XV:const AXIS_OF: Record<FacetId, AxisId> = { A1: "A", A2: "A", B1: "B", B2: "B" };
109#PQ:const AXIS_NAMES: Record<AxisId, string> = { A: "Solar Height", B: "Tidal Direction" };
110#JH:const QUADRANT_NAMES = ["Summer", "Autumn", "Winter", "Spring"];
111#HR:const QUADRANT_ARCHETYPES = ["The Zenith", "The Turning", "The Deep", "The Greening"];
112#QJ:
113#WY:// facet → item indices
114#SJ:const FACET_ITEMS: Record<FacetId, number[]> = {} as any;
115#QM:for (const f of FACETS) FACET_ITEMS[f] = [];
116#VW:ITEMS.forEach((item, i) => FACET_ITEMS[item.facet].push(i));
