118#WK:// ── HELPERS ────────────────────────────────────────────
119#PZ:function clamp(v: number, lo: number, hi: number): number {
120#WR:  return Math.max(lo, Math.min(hi, Math.round(v)));
121#WK:}
122#JQ:
123#YR:function gauss(mean: number, std: number): number {
124#PQ:  // Box-Muller
125#XJ:  let u = 0, v = 0;
126#JW:  while (u === 0) u = Math.random();
127#MR:  while (v === 0) v = Math.random();
128#KX:  return mean + std * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
129#PV:}
130#PX:
131#BJ:function choice<T>(arr: T[]): T {
132#ZQ:  return arr[Math.floor(Math.random() * arr.length)];
133#VR:}
134#QZ:
135#BK:// ── SCORING ENGINE ─────────────────────────────────────
136#TM:function score(rawResponses: number[], orientations?: number[]): ScoreResult {
137#MH:  if (rawResponses.length !== 32) throw new Error(`Need 32 responses, got ${rawResponses.length}`);
138#NY:  const ori = orientations ?? new Array(32).fill(1);
139#QR:
140#MV:  // Step 2: Normalize
141#HV:  const normalized: number[] = [];
142#QQ:  for (let i = 0; i < 32; i++) {
143#WK:    normalized.push(ori[i] === 1 ? rawResponses[i] : 8 - rawResponses[i]);
144#ZJ:  }
145#VM:
146#KB:  // Step 3: Facet scores
147#NB:  const facets = {} as Record<FacetId, FacetResult>;
148#NB:  for (const facet of FACETS) {
149#TW:    const idxs = FACET_ITEMS[facet];
150#NQ:    const norms = idxs.map(i => normalized[i]);
151#QN:    const sum = norms.reduce((a, b) => a + b, 0);
152#NK:    const mean = sum / 8;
153#SW:    const scoreVal = (mean - 1) / 6 * 100;
154#TV:    const variance = norms.reduce((a, n) => a + (n - mean) ** 2, 0) / 8;
155#YP:    facets[facet] = { norms, sum, mean, score: scoreVal, variance };
156#PT:  }
157#HJ:
158#WK:  // Step 4: Axis scores
159#SH:  const axis = {
160#XS:    A: { score: (facets.A1.score + facets.A2.score) / 2 },
161#VY:    B: { score: (facets.B1.score + facets.B2.score) / 2 },
162#MW:  };
163#VQ:
164#XN:  // Step 5: Position
165#KW:  const a_off = axis.A.score - 50;
166#HW:  const b_off = axis.B.score - 50;
167#QZ:
168#QJ:  // Step 6: Distance & prototypicality
169#SR:  const MAX_DIST = Math.sqrt(50 * 50 + 50 * 50); // ≈70.7107
170#WP:  const distance = Math.sqrt(a_off * a_off + b_off * b_off);
171#KM:  const prototypicality = distance / MAX_DIST;
172#VK:
173#VB:  // Step 7: Angle
174#NQ:  const angle_rad = Math.atan2(b_off, a_off);
175#VH:  let angle_deg = angle_rad * 180 / Math.PI;
176#PK:  if (angle_deg < 0) angle_deg += 360;
177#HM:
178#WT:  // Step 8: Quadrant
179#MV:  let quadrant: number;
180#VS:  if (a_off >= 0 && b_off >= 0) quadrant = 0;
181#JY:  else if (a_off >= 0 && b_off < 0) quadrant = 1;
182#SM:  else if (a_off < 0 && b_off < 0) quadrant = 2;
183#VZ:  else quadrant = 3;
184#NB:
185#MN:  // Step 9: Gradation — angle within quadrant
186#YN:  // Angle order going CCW from 0° (A>50, B=50):
187#JR:  //   0–90° = Summer (A>50, B>50)
188#NN:  //   90–180° = Spring (A<50, B>50)
189#MN:  //   180–270° = Winter (A<50, B<50)
190#BW:  //   270–360° = Autumn (A>50, B<50)
191#YV:  // Quadrant numbering: 0=Summer, 1=Autumn, 2=Winter, 3=Spring
192#WM:  // So the angle start per quadrant is NOT quadrant*90. Use explicit map.
193#WW:  const QUAD_ANGLE_START = [0, 270, 180, 90]; // Summer, Autumn, Winter, Spring
194#VR:  const quad_start = QUAD_ANGLE_START[quadrant];
195#VJ:  let angle_in_quad = ((angle_deg - quad_start) + 360) % 360;
196#BJ:  // Normalize: angle_in_quad should be 0-90. If > 90, we're in the wrong quadrant
197#RS:  // (shouldn't happen with correct mapping, but guard anyway)
198#ZM:  if (angle_in_quad > 90) angle_in_quad = angle_in_quad - 90;
199#RS:  let gradation: string;
200#XT:  if (angle_in_quad < 30) gradation = "Early";
201#MB:  else if (angle_in_quad < 60) gradation = "Mid";
202#NY:  else gradation = "Late";
203#QQ:
204#XJ:  // Step 10: Threshold
205#XZ:  const is_threshold = prototypicality < 0.28;
206#XQ:
207#PZ:  // Facet contribution
208#BB:  const contrib: Record<AxisId, FacetContrib> = {} as any;
209#RR:  for (const [ax, [f1, f2]] of [["A", ["A1", "A2"]] as [AxisId, [FacetId, FacetId]], ["B", ["B1", "B2"]] as [AxisId, [FacetId, FacetId]]]) {
210#VM:    const s1 = facets[f1].score;
211#XR:    const s2 = facets[f2].score;
212#PY:    const d1 = Math.abs(s1 - 50);
213#SN:    const d2 = Math.abs(s2 - 50);
214#ZR:    let dom: string;
215#VT:    if (Math.abs(s1 - s2) < 0.01) dom = "equal";
216#ZN:    else dom = d1 > d2 ? f1 : f2;
217#YH:    contrib[ax] = { dominant: dom, s1, s2, d1, d2 };
218#ZH:  }
219#MH:
220#JW:  // Facet consistency (std dev of normalized responses within facet)
221#NT:  const facet_consistency = {} as Record<FacetId, number>;
222#YP:  for (const f of FACETS) facet_consistency[f] = Math.sqrt(facets[f].variance);
223#MK:
224#ZV:  return {
225#WM:    name: "",
226#YQ:    raw: rawResponses,
227#SS:    normalized,
228#MN:    facets,
229#QS:    axis,
230#WR:    a_off, b_off,
231#WY:    distance, prototypicality,
232#RS:    angle_deg, angle_in_quad,
233#SR:    quadrant, quadrant_name: QUADRANT_NAMES[quadrant],
234#YS:    gradation,
235#KS:    is_threshold,
236#HJ:    contrib,
237#NX:    facet_consistency,
238#PN:    _orient: ori,
239#KP:  };
240#MP:}
241#QW:
242#XX:// ── RESPONDENT GENERATORS ─────────────────────────────
243#PM:function gen(
244#QK:  name: string,
245#BP:  a1_center: number, a2_center: number,
246#BW:  b1_center: number, b2_center: number,
247#RM:  noise = 1.0,
248#NN:): [string, number[], number[]] {
249#SK:  // Generate orientations FIRST, then produce raw responses consistent with them.
250#RX:  // A high-Bright respondent with ori=-1 (Bright on LEFT) should pick pip ~1 (left),
251#VJ:  // NOT pip ~7. This way normalization (8-1=7) correctly recovers the high-Bright signal.
252#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
253#MN:  const centers: Record<FacetId, number> = { A1: a1_center, A2: a2_center, B1: b1_center, B2: b2_center };
254#KK:  const raw: number[] = [];
255#WY:  for (let i = 0; i < ITEMS.length; i++) {
256#SK:    const item = ITEMS[i];
257#SX:    const c = centers[item.facet];
258#BB:    // trait = what the respondent would pick if Bright/Outward were always on the right
259#HZ:    const trait = clamp(gauss(c, noise), 1, 7);
260#YV:    // orientation-aware raw: if ori=-1 (Bright on LEFT), a high-trait person picks left (low raw)
261#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
262#YH:    raw.push(r);
263#TS:  }
264#NN:  return [name, raw, orient];
265#NM:}
266#XK:
267#JV:function genExtreme(name: string, a_center: number, b_center: number): [string, number[], number[]] {
268#BH:  return gen(name, a_center, a_center, b_center, b_center, 0.4);
269#HR:}
270#ZB:
271#MQ:function genMixed(
272#QQ:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, noise = 0.6,
273#NN:): [string, number[], number[]] {
274#ZR:  return gen(name, a1_c, a2_c, b1_c, b2_c, noise);
275#YP:}
276#MH:
277#TM:function genNoisy(
278#HP:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, noise = 2.0,
279#NN:): [string, number[], number[]] {
280#ZR:  return gen(name, a1_c, a2_c, b1_c, b2_c, noise);
281#PT:}
282#QT:
283#TW:function genBias(
284#ZR:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, biasSide: "right" | "left",
285#NN:): [string, number[], number[]] {
286#HK:  // Same orientation-aware approach as gen(), plus a bias shift on the trait.
287#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
288#KH:  const centers: Record<FacetId, number> = { A1: a1_c, A2: a2_c, B1: b1_c, B2: b2_c };
289#NW:  const shift = biasSide === "right" ? 1.5 : -1.5;
290#KK:  const raw: number[] = [];
291#WY:  for (let i = 0; i < ITEMS.length; i++) {
292#SK:    const item = ITEMS[i];
293#SX:    const c = centers[item.facet];
294#YR:    const trait = clamp(gauss(c + shift, 0.3), 1, 7);
295#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
296#YH:    raw.push(r);
297#ZV:  }
298#NN:  return [name, raw, orient];
299#SN:}
