301#JN:// ── BUILD 30+ RESPONDENTS ─────────────────────────────
302#JX:const seed = 42;
303#VV:// Simple seeded random for reproducibility
304#NM:let _seed = seed;
305#NN:function seededRandom(): number {
306#VP:  _seed = (_seed * 16807) % 2147483647;
307#KB:  return (_seed - 1) / 2147483646;
308#HW:}
309#HX:// Override Math.random temporarily during generation
310#YM:const _origRandom = Math.random;
311#KZ:Math.random = seededRandom;
