313#ZS:const respondents: [string, number[], number[]][] = [];
314#RN:
315#JS:// Core archetypes — each quadrant
316#WS:respondents.push(genExtreme("Summer-Pure", 6.5, 6.5));
317#QQ:respondents.push(genExtreme("Autumn-Pure", 6.5, 1.5));
318#YB:respondents.push(genExtreme("Winter-Pure", 1.5, 1.5));
319#SZ:respondents.push(genExtreme("Spring-Pure", 1.5, 6.5));
320#TW:
321#KW:// Mild versions
322#MV:respondents.push(genExtreme("Summer-Mild", 5.5, 5.5));
323#TR:respondents.push(genExtreme("Autumn-Mild", 5.5, 2.5));
324#VH:respondents.push(genExtreme("Winter-Mild", 2.5, 2.5));
325#JV:respondents.push(genExtreme("Spring-Mild", 2.5, 5.5));
