 290#XX:// ── RESPONDENT GENERATORS ─────────────────────────────
 291#PM:function gen(
 292#QK:  name: string,
 293#BP:  a1_center: number, a2_center: number,
 294#BW:  b1_center: number, b2_center: number,
 295#RM:  noise = 1.0,
 296#NN:): [string, number[], number[]] {
 297#SK:  // Generate orientations FIRST, then produce raw responses consistent with them.
 298#RX:  // A high-Bright respondent with ori=-1 (Bright on LEFT) should pick pip ~1 (left),
 299#VJ:  // NOT pip ~7. This way normalization (8-1=7) correctly recovers the high-Bright signal.
 300#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
 301#MN:  const centers: Record<FacetId, number> = { A1: a1_center, A2: a2_center, B1: b1_center, B2: b2_center };
 302#KK:  const raw: number[] = [];
 303#WY:  for (let i = 0; i < ITEMS.length; i++) {
 304#SK:    const item = ITEMS[i];
 305#SX:    const c = centers[item.facet];
 306#BB:    // trait = what the respondent would pick if Bright/Outward were always on the right
 307#HZ:    const trait = clamp(gauss(c, noise), 1, 7);
 308#YV:    // orientation-aware raw: if ori=-1 (Bright on LEFT), a high-trait person picks left (low raw)
 309#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
 310#YH:    raw.push(r);
 311#SP:  }
 312#NN:  return [name, raw, orient];
 313#PB:}
