 319#MQ:function genMixed(
 320#QQ:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, noise = 0.6,
 321#NN:): [string, number[], number[]] {
 322#ZR:  return gen(name, a1_c, a2_c, b1_c, b2_c, noise);
 323#KH:}
 324#NW:
 325#TM:function genNoisy(
 326#HP:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, noise = 2.0,
 327#NN:): [string, number[], number[]] {
 328#ZR:  return gen(name, a1_c, a2_c, b1_c, b2_c, noise);
 329#ZR:}
 330#MB:
 331#TW:function genBias(
 332#ZR:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, biasSide: "right" | "left",
 333#NN:): [string, number[], number[]] {
 334#HK:  // Same orientation-aware approach as gen(), plus a bias shift on the trait.
 335#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
 336#KH:  const centers: Record<FacetId, number> = { A1: a1_c, A2: a2_c, B1: b1_c, B2: b2_c };
 337#NW:  const shift = biasSide === "right" ? 1.5 : -1.5;
 338#KK:  const raw: number[] = [];
 339#WY:  for (let i = 0; i < ITEMS.length; i++) {
 340#SK:    const item = ITEMS[i];
 341#SX:    const c = centers[item.facet];
 342#YR:    const trait = clamp(gauss(c + shift, 0.3), 1, 7);
 343#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
 344#YH:    raw.push(r);
 345#MT:  }
 346#NN:  return [name, raw, orient];
 347#TZ:}
