 302#XX:// ── RESPONDENT GENERATORS ─────────────────────────────
 303#PM:function gen(
 304#QK:  name: string,
 305#BP:  a1_center: number, a2_center: number,
 306#BW:  b1_center: number, b2_center: number,
 307#RM:  noise = 1.0,
 308#NN:): [string, number[], number[]] {
 309#SK:  // Generate orientations FIRST, then produce raw responses consistent with them.
 310#RX:  // A high-Bright respondent with ori=-1 (Bright on LEFT) should pick pip ~1 (left),
 311#VJ:  // NOT pip ~7. This way normalization (8-1=7) correctly recovers the high-Bright signal.
 312#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
 313#MN:  const centers: Record<FacetId, number> = { A1: a1_center, A2: a2_center, B1: b1_center, B2: b2_center };
 314#KK:  const raw: number[] = [];
 315#WY:  for (let i = 0; i < ITEMS.length; i++) {
 316#SK:    const item = ITEMS[i];
 317#SX:    const c = centers[item.facet];
 318#BB:    // trait = what the respondent would pick if Bright/Outward were always on the right
 319#HZ:    const trait = clamp(gauss(c, noise), 1, 7);
 320#YV:    // orientation-aware raw: if ori=-1 (Bright on LEFT), a high-trait person picks left (low raw)
 321#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
 322#YH:    raw.push(r);
 323#SX:  }
 324#NN:  return [name, raw, orient];
 325#QY:}
