 343#TW:function genBias(
 344#ZR:  name: string, a1_c: number, a2_c: number, b1_c: number, b2_c: number, biasSide: "right" | "left",
 345#NN:): [string, number[], number[]] {
 346#HK:  // Same orientation-aware approach as gen(), plus a bias shift on the trait.
 347#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
 348#KH:  const centers: Record<FacetId, number> = { A1: a1_c, A2: a2_c, B1: b1_c, B2: b2_c };
 349#NW:  const shift = biasSide === "right" ? 1.5 : -1.5;
 350#KK:  const raw: number[] = [];
 351#WY:  for (let i = 0; i < ITEMS.length; i++) {
 352#SK:    const item = ITEMS[i];
