 354#YR:    const trait = clamp(gauss(c + shift, 0.3), 1, 7);
 355#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
 356#YH:    raw.push(r);
 357#KQ:  }
 358#NN:  return [name, raw, orient];
