const fs=require('fs');
const bankIds = ['A1.1','A1.2','A1.4','A1.6','A2.1','A2.2','A2.3','A2.6','B1.2','B1.3','B1.5','B1.6','B2.1','B2.2','B2.3','B2.6'];
const html=fs.readFileSync('sca-debug.html','utf8');
const ids=[...html.matchAll(/id:'([AB][12]\.\d)'/g)].map(m=>m[1]);
const missing = bankIds.filter(id=>!ids.includes(id));
console.log('bank size:', ids.length, '| SCA-16 declared:', bankIds.length);
console.log(missing.length? 'MISSING: '+missing.join(', ') : 'all 16 present in bank ✓');
// facet balance
const byFacet={}; bankIds.forEach(id=>{const f=id.slice(0,2);byFacet[f]=(byFacet[f]||0)+1;});
console.log('facet balance:', JSON.stringify(byFacet));
"
echo "=== two-lengths reflected across docs ==="
grep -cl "SCA-16" docs/*.md
echo "=== stale absolute '32 items' that ignores short form (expect only historical changelog) ==="
grep -rn "32 items, facet-organized\|32 items per test" docs/*.md | grep -v CHANGELOG | head

