  672#QX:function generateDebugText(d) {
  673#PR:  const L = '\n';
  674#YS:  let t = '';
  675#JM:  const h = (s) => { t += L + '═══ ' + s + ' ═══' + L; };
  676#XK:  const s = (label, val) => { t += label + ': ' + val + L; };
  677#RK:  const f = (label, val) => { t += '  ' + label + ' = ' + val + L; };
  678#MQ:
  679#BQ:  t += 'SOLSTICE CYCLE ASSESSMENT — DEBUG REPORT' + L;
  680#VQ:  t += '=========================================' + L;
  681#KB:  t += 'Generated: ' + new Date().toISOString() + L;
  682#ZK:
  683#NS:  h('STEP 1 — Raw Answers (32 items)');
  684#RS:  t += 'Orientation: +1 = Bright/Outward pole on RIGHT (raw 7 = max). -1 = flipped in normalization.' + L + L;
  685#QN:  d.rawAnswers.forEach(a => {
  686#QR:    t += '  ' + a.id + ' [' + a.facet + ']'.padEnd(8) + ' raw=' + a.raw + '  ori=' + (a.orientation>0?'+1':'-1').padEnd(3);
  687#MR:    t += '  A="' + a.poleADesc + '"  B="' + a.poleBDesc + '"' + L;
  688#MH:  });
  689#KN:
  690#ZH:  h('STEP 2 — Normalization');
  691#QH:  t += 'Rule: if ori=-1 → norm = 8 − raw. Higher norm = more Bright/Outward.' + L + L;
  692#QT:  d.normalized.forEach(a => {
  693#KK:    const flipped = a.raw !== a.normalized ? ' ← FLIPPED' : '';
  694#MN:    t += '  ' + a.id.padEnd(6) + ' raw=' + a.raw + ' → norm=' + a.normalized + flipped + L;
  695#TR:  });
  696#KW:
  697#NS:  h('STEP 3 — Facet Scores');
  698#KV:  t += 'Formula: facet score = (mean(normalized) − 1) / 6 × 100. Range 0–100.' + L;
  699#YR:  FACETS.forEach(facet => {
  700#JN:    const f = d.facets[facet];
  701#YY:    t += L + '  ' + facet + ' — ' + FACET_NAMES[facet] + ' (' + AXIS_NAMES[AXIS_OF[facet]] + ')' + L;
  702#WZ:    f.items.forEach(it => { t += '    ' + it.id + ' norm=' + it.norm + L; });
  703#KM:    t += '    Sum = ' + f.sum + L;
  704#RQ:    t += '    Mean = ' + f.mean.toFixed(4) + L;
  705#PM:    t += '    Score = ' + f.score.toFixed(4) + L;
  706#QM:    t += '    Formula: (' + f.items.map(it=>it.norm).join('+') + ') / 8 = ' + f.mean.toFixed(4) + '; (' + f.mean.toFixed(4) + ' − 1) / 6 × 100 = ' + f.score.toFixed(2) + L;
  707#HX:  });
  708#KZ:
  709#WB:  h('STEP 4 — Axis Scores');
  710#BM:  t += 'Formula: axis score = mean of its 2 facet scores (both already 0–100).' + L;
  711#WM:  ['A','B'].forEach(axis => {
  712#PY:    const a = d.axis[axis];
  713#NP:    const fA = axis === 'A' ? 'A1' : 'B1';
  714#SH:    const fB = axis === 'A' ? 'A2' : 'B2';
  715#ZR:    t += L + '  Axis ' + axis + ' — ' + AXIS_NAMES[axis] + L;
  716#WQ:    t += '    ' + fA + ' = ' + a.facetScores[fA].toFixed(4) + L;
  717#HR:    t += '    ' + fB + ' = ' + a.facetScores[fB].toFixed(4) + L;
  718#WX:    t += '    Score = ' + a.score.toFixed(4) + L;
  719#KW:  });
  720#RT:
  721#XV:  h('STEP 5 — Position Relative to Center (50, 50)');
  722#VW:  t += '  A − 50 = ' + d.position.aOff.toFixed(4) + L;
  723#JQ:  t += '  B − 50 = ' + d.position.bOff.toFixed(4) + L;
  724#TV:
  725#TK:  h('STEP 6 — Distance & Prototypicality');
  726#JJ:  t += 'Formula: distance = √(A_off² + B_off²). max = √(50² + 50²) = 70.71. proto = distance / 70.71.' + L;
  727#HY:  t += '  Distance = ' + d.distance.distance.toFixed(4) + L;
  728#YS:  t += '  Max = ' + d.distance.maxDist + L;
  729#VY:  t += '  Prototypicality = ' + d.distance.prototypicality.toFixed(4) + L;
  730#TX:  t += '  Calculation: √((' + d.position.aOff.toFixed(2) + ')² + (' + d.position.bOff.toFixed(2) + ')²) = ' + d.distance.distance.toFixed(3) + ' / 70.71 = ' + d.distance.prototypicality.toFixed(4) + L;
  731#ZQ:
  732#QY:  h('STEP 7 — Angle');
  733#PX:  t += 'Formula: angle = atan2(B_off, A_off). 0°=right (A>50,B=50), CCW. Summer 0–90°, Spring 90–180°, Winter 180–270°, Autumn 270–360°.' + L;
  734#QM:  t += '  Radians = ' + d.angle.rad.toFixed(4) + L;
  735#RM:  t += '  Degrees = ' + d.angle.deg.toFixed(4) + '°' + L;
  736#HQ:  t += '  Calculation: atan2(' + d.position.bOff.toFixed(2) + ', ' + d.position.aOff.toFixed(2) + ') = ' + d.angle.rad.toFixed(4) + ' rad = ' + d.angle.deg.toFixed(2) + '°' + L;
  737#NW:
  738#YN:  h('STEP 8 — Quadrant Determination');
  739#ZX:  t += 'Rule: A≥50,B≥50=Summer | A≥50,B<50=Autumn | A<50,B<50=Winter | A<50,B≥50=Spring' + L;
  740#KW:  t += '  ' + d.quadrant.rule + L;
