  746#VK:  t += '  Progress = ' + d.gradation.progress.toFixed(4) + '° (0 at entry, →90 at exit)' + L;
  747#HN:  t += '  Band = ' + d.gradation.band + L;
  748#WB:
  749#BW:  h('STEP 10 — Facet Tension & Classification');
  750#HT:  t += 'Tension rule: axis tense if its two facets are on opposite sides of 50 AND both ≥ ' + TENSION_MARGIN + ' from 50.' + L;
  751#WM:  ['A','B'].forEach(axis => {
  752#KR:    t += '  Axis ' + axis + ' (' + AXIS_NAMES[axis] + '): ' + d.tension[axis].label + ' — ' + d.tension[axis].rule + L;
  753#VJ:  });
  754#HH:  t += '  Classification: ' + d.classify.rule + L;
  755#NV:  t += '  → ' + (d.classify.resultType === 'Threshold'
  756#BV:       ? 'THRESHOLD (boundary condition, NOT a type) — ' + (d.classify.hasTension ? 'with facet-tension modifier (NOT balanced; read facet signature)' : 'genuinely balanced / equinox')
  757#QM:       : 'CLEAR SEASON — ' + d.quadrant.name + (d.classify.hasTension ? ' (with facet-tension modifier)' : '')) + L;
  758#XS:  t += '  Type count is unchanged: 4 seasonal types (clusters). Threshold is a boundary; tension is a modifier.' + L;
  759#ST:
  760#JN:  h('STEP 11 — Facet Contribution Analysis');
  761#ZQ:  t += 'Rule: which facet\'s score is further from 50? That facet drove the axis.' + L;
  762#WM:  ['A','B'].forEach(axis => {
  763#WP:    const fc = d.facetContrib[axis];
  764#TQ:    const facets = axis === 'A' ? ['A1','A2'] : ['B1','B2'];
  765#ZR:    t += L + '  Axis ' + axis + ' — ' + AXIS_NAMES[axis] + L;
  766#BN:    t += '    ' + FACET_NAMES[facets[0]] + ' = ' + fc.s1.toFixed(4) + ' (offset from 50: ' + fc.d1.toFixed(4) + ')' + L;
  767#TN:    t += '    ' + FACET_NAMES[facets[1]] + ' = ' + fc.s2.toFixed(4) + ' (offset from 50: ' + fc.d2.toFixed(4) + ')' + L;
  768#VJ:    t += '    Dominant: ' + fc.dominantLabel + L;
  769#VW:  });
  770#ZZ:
  771#PS:  h('STEP 12 — Final Result');
  772#KM:  t += '  Result type: ' + d.result.label + L;
  773#JJ:  t += '  Color class: ' + d.result.color + L;
  774#NV:
  775#BX:  h('SUMMARY TABLE');
  776#NY:  t += '  A1     A2     Axis A   B1     B2     Axis B   Proto    Angle    Quadrant   Grad   Result' + L;
  777#ZH:  t += '  ' + [
  778#XH:    d.facets.A1.score.toFixed(1).padEnd(6),
  779#SQ:    d.facets.A2.score.toFixed(1).padEnd(6),
  780#PH:    d.axis.A.score.toFixed(1).padEnd(8),
  781#PR:    d.facets.B1.score.toFixed(1).padEnd(6),
