274#XB:function renderQuestion() {
275#PB:  const item = activeBank[currentIdx];
276#QN:  const ori = orientations[currentIdx];
277#HZ:  const resp = responses[currentIdx];
278#KH:  let html = `<div class="question-block">`;
279#SQ:  html += `<div class="facet-badge">${item.id} — ${FACET_NAMES[item.facet]} (${AXIS_NAMES[AXIS_OF[item.facet]]})</div>`;
280#SQ:  html += `<div class="question-stem">${item.stem}</div>`;
281#ZW:  html += `<div class="scale-container">`;
282#VS:  const leftPole = ori === 1 ? item.poleB : item.poleA;
283#KW:  const rightPole = ori === 1 ? item.poleA : item.poleB;
284#TM:  html += `<div class="pole-label left">${leftPole}</div>`;
285#MV:  html += `<div class="pips">`;
286#HM:  for (let v = 1; v <= 7; v++) {
287#MK:    const checked = resp === v ? 'checked' : '';
288#KK:    html += `<input type="radio" name="q${currentIdx}" value="${v}" id="q${currentIdx}_${v}" class="pip-radio" ${checked} onchange="selectAnswer(${v})">`;
289#JM:    html += `<label for="q${currentIdx}_${v}" class="pip-label">${v}</label>`;
290#VP:  }
291#VK:  html += `</div>`;
292#XK:  html += `<div class="pole-label right">${rightPole}</div>`;
293#YY:  html += `</div></div>`;
294#HV:  document.getElementById('question-container').innerHTML = html;
295#WB:  const answered = responses.filter(r => r !== null).length;
296#RR:  const total = activeBank.length;
297#MH:  document.getElementById('progress-fill').style.width = (answered / total * 100) + '%';
298#TR:  document.getElementById('progress-text').textContent = `${answered} / ${total}${activeLength===16?' (MMA-16)':''}`;
299#JQ:  document.getElementById('btn-prev').disabled = currentIdx === 0;
300#SM:  document.getElementById('btn-next').disabled = responses[currentIdx] === null;
301#HZ:}
