308#JK:// SCORING ENGINE (same 13-step model as SCA)
309#TY:// ══════════════════════════════════════════════════
310#TR:function score() {
311#KJ:  const d = {};
312#PP:  d.rawAnswers = [];
313#HQ:  activeBank.forEach((item, i) => {
314#KH:    d.rawAnswers.push({ id: item.id, facet: item.facet, raw: responses[i], orientation: orientations[i], poleADesc: item.poleA, poleBDesc: item.poleB });
315#PM:  });
316#QZ:  d.normalized = d.rawAnswers.map(a => { const norm = a.orientation === 1 ? a.raw : (8 - a.raw); return { ...a, normalized: norm }; });
317#VV:  d.facets = {};
318#YR:  FACETS.forEach(facet => {
319#TW:    const idxs = FACET_ITEMS[facet];
320#PW:    const norms = idxs.map(i => d.normalized[i].normalized);
321#YM:    const sum = norms.reduce((a,b) => a + b, 0);
322#MB:    const n = idxs.length;
323#PJ:    const mean = sum / n;
324#SW:    const scoreVal = (mean - 1) / 6 * 100;
325#MM:    d.facets[facet] = { items: idxs.map(i => ({ id: activeBank[i].id, raw: responses[i], norm: d.normalized[i].normalized })), sum, mean, score: scoreVal, formula: `(${norms.map(x=>x.toFixed(0)).join(' + ')}) / ${n} = ${mean.toFixed(3)}; (${mean.toFixed(3)} - 1) / 6 × 100 = ${scoreVal.toFixed(2)}` };
326#JJ:  });
327#QR:  d.axis = {};
328#BV:  ['C','D'].forEach(axis => {
329#SM:    const facets = axis === 'C' ? ['C1','C2'] : ['D1','D2'];
330#NN:    const fA = d.facets[facets[0]].score, fB = d.facets[facets[1]].score;
331#WV:    const scoreVal = (fA + fB) / 2;
332#QH:    d.axis[axis] = { score: scoreVal, facetScores: { [facets[0]]: fA, [facets[1]]: fB }, formula: `(${fA.toFixed(2)} + ${fB.toFixed(2)}) / 2 = ${scoreVal.toFixed(2)}` };
333#VY:  });
334#VH:  const cOff = d.axis.C.score - 50, dOff = d.axis.D.score - 50;
335#BV:  d.position = { cOff, dOff };
336#NP:  const distance = Math.sqrt(cOff * cOff + dOff * dOff);
337#QV:  const MAX_DIST = 70.71;
338#KM:  const prototypicality = distance / MAX_DIST;
339#QV:  d.distance = { distance, maxDist: MAX_DIST, prototypicality, formula: `√((${cOff.toFixed(2)})² + (${dOff.toFixed(2)})²) = ${distance.toFixed(3)};  ${distance.toFixed(3)} / ${MAX_DIST} = ${prototypicality.toFixed(4)}` };
340#WY:  const angleRad = Math.atan2(dOff, cOff);
341#WX:  let angleDeg = angleRad * 180 / Math.PI;
342#RS:  if (angleDeg < 0) angleDeg += 360;
343#XM:  d.angle = { rad: angleRad, deg: angleDeg, formula: `atan2(${dOff.toFixed(2)}, ${cOff.toFixed(2)}) = ${angleRad.toFixed(4)} rad = ${angleDeg.toFixed(2)}°` };
344#VZ:  let quadrant;
345#WP:  if (cOff >= 0 && dOff >= 0) quadrant = 0;
346#XW:  else if (cOff >= 0 && dOff < 0) quadrant = 1;
347#NQ:  else if (cOff < 0 && dOff < 0) quadrant = 2;
348#VZ:  else quadrant = 3;
349#NR:  d.quadrant = { index: quadrant, name: QUADRANT_NAMES[quadrant], archetype: QUADRANT_ARCHETYPES[quadrant], rule: `C${cOff>=0?'≥':'<'}50, D${dOff>=0?'≥':'<'}50 → ${QUADRANT_NAMES[quadrant]}` };
350#TV:  const entryEdge = QUAD_ENTRY_EDGE[quadrant];
351#PY:  const progress = (entryEdge - angleDeg + 360) % 360;
352#BJ:  let gradation;
353#BS:  if (progress < 30) gradation = 'Early';
354#HX:  else if (progress < 60) gradation = 'Mid';
355#PT:  else gradation = 'Late';
356#XM:  d.gradation = { entryEdge, progress, band: gradation, rule: `Cycle entry edge for ${QUADRANT_NAMES[quadrant]} = ${entryEdge}°; progress = (${entryEdge} − ${angleDeg.toFixed(2)} + 360) mod 360 = ${progress.toFixed(2)}° → ${gradation}` };
357#SW:
358#ZQ:  const isNearCenter = prototypicality < 0.28;
359#YP:  d.tension = {};
360#BV:  ['C','D'].forEach(axis => {
361#SM:    const facets = axis === 'C' ? ['C1','C2'] : ['D1','D2'];
362#YQ:    const s1 = d.facets[facets[0]].score, s2 = d.facets[facets[1]].score;
363#QJ:    const o1 = s1 - 50, o2 = s2 - 50;
364#XN:    const opposite = (o1 * o2) < 0;
365#RP:    const strong = Math.abs(o1) >= TENSION_MARGIN && Math.abs(o2) >= TENSION_MARGIN;
366#XH:    const tense = opposite && strong;
367#RK:    let label;
368#ZR:    if (tense) { const hi = o1 > 0 ? facets[0] : facets[1]; const lo = o1 > 0 ? facets[1] : facets[0]; label = `tense — pulled between ${FACET_POLES[hi][0]} and ${FACET_POLES[lo][1]}`; }
369#ZP:    else label = 'coherent';
370#RQ:    d.tension[axis] = { s1, s2, opposite, strong, tense, label, rule: `${FACET_NAMES[facets[0]]}=${s1.toFixed(1)} (${o1>=0?'+':''}${o1.toFixed(1)}), ${FACET_NAMES[facets[1]]}=${s2.toFixed(1)} (${o2>=0?'+':''}${o2.toFixed(1)}); opposite=${opposite}, both≥${TENSION_MARGIN}=${strong} → ${tense?'TENSION':'coherent'}` };
371#WJ:  });
372#XS:  const hasTension = d.tension.C.tense || d.tension.D.tense;
373#YP:  let resultType, resultLabel, resultColor;
374#BW:  if (!isNearCenter) {
375#YJ:    resultType = QUADRANT_NAMES[quadrant];
376#VX:    resultLabel = `${gradation} ${QUADRANT_NAMES[quadrant]}`;
377#PX:    resultColor = QUADRANT_COLORS[quadrant];
378#SJ:  } else {
379#MK:    resultType = 'HaltingPoint';
380#NJ:    resultLabel = hasTension ? '⏸️ The Halting Point · facet tension' : '⏸️ The Halting Point';
381#ZV:    resultColor = 'threshold-c';
382#WS:  }
