  1#SW:#!/usr/bin/env bun
  2#MY:/**
  3#NY: * MMA Simulation & Analysis Script (TypeScript / Bun)
  4#YW: * Generates 30+ synthetic respondents with diverse cognitive-style answer
  5#TB: * patterns, scores them through the full MMA pipeline for both lengths
  6#MP: * (MMA-32 and MMA-16), and runs a self-consistency + cross-length audit.
  7#NB: *
  8#WJ: * WHAT THIS IS: a verification harness for the scoring engine. It checks that
  9#KQ: * normalization, facet/axis scoring, distance, angle, gradation, facet-tension
 10#HJ: * and classification behave as specified, and that boundary/corner cases resolve.
 11#KX: *
 12#MQ: * WHAT THIS IS NOT: pilot data, validation, or evidence of reliability, construct
 13#PB: * validity, or population norms. The "expected vs actual" checks are tautological
 14#MW: * by construction — the same centers generate the respondents and define the
 15#RV: * expectations; synthetic respondents have no psychology. Per the framework's
 16#PH: * honest-ceiling rule (00 §2.1), nothing here moves the MMA from "theory-informed"
 17#WH: * toward "validated". Do not cite it as such.
 18#BN: *
 19#VQ: * Usage: bun run mma-simulate.ts
 20#ST: * Output: Terminal report + mma-sim-results.csv + mma-sim-results-16.csv
 21#XH: */
 22#ZP:
 23#SN:// ── TYPES ──────────────────────────────────────────────
 24#WM:type FacetId = "C1" | "C2" | "D1" | "D2";
 25#SJ:type AxisId = "C" | "D";
 26#HK:
 27#SP:interface Item {
 28#XJ:  id: string;
 29#TT:  facet: FacetId;
 30#BR:  poleA: string;
 31#JM:  poleB: string;
 32#PY:}
 33#QY:
 34#WP:interface FacetResult {
 35#VQ:  norms: number[];
 36#PR:  sum: number;
 37#NS:  mean: number;
 38#HS:  score: number;
 39#SR:  variance: number;
 40#KR:}
 41#BH:
 42#HB:interface AxisResult {
 43#HS:  score: number;
 44#KR:}
 45#KT:
 46#YB:interface FacetContrib {
 47#NM:  dominant: string;
 48#BK:  s1: number;
 49#KK:  s2: number;
 50#JB:  d1: number;
 51#WM:  d2: number;
 52#SJ:}
 53#NB:
 54#MZ:interface ScoreResult {
 55#MZ:  name: string;
 56#BM:  raw: number[];
 57#PX:  normalized: number[];
 58#KH:  facets: Record<FacetId, FacetResult>;
 59#RQ:  axis: Record<AxisId, AxisResult>;
 60#PZ:  c_off: number;
 61#ZM:  d_off: number;
 62#RK:  distance: number;
 63#MN:  prototypicality: number;
 64#BP:  angle_deg: number;
 65#BY:  angle_in_quad: number;
 66#PJ:  quadrant: number;
 67#QW:  quadrant_name: string;
 68#BP:  gradation: string;
 69#MQ:  is_near_center: boolean;
 70#BT:  is_threshold: boolean;
 71#SH:  has_tension: boolean;
 72#BX:  result_type: string;
 73#JY:  contrib: Record<AxisId, FacetContrib>;
 74#NX:  facet_consistency: Record<FacetId, number>;
 75#MP:  _orient: number[];
 76#KK:}
 77#VB:
 78#TV:// ── ITEM BANK ──────────────────────────────────────────
 79#SB:const ITEMS: Item[] = [
 80#KB:  // C1 — Deliberation Preference (8)
 81#QK:  { id: "C1.1", facet: "C1", poleA: "Reading something challenging, working on a puzzle, or exploring an idea.", poleB: "Relaxing with something that doesn't require much thought." },
 82#NM:  { id: "C1.2", facet: "C1", poleA: "Understand the principles first, deliberately.", poleB: "Pick it up by doing, before I have the theory." },
 83#MV:  { id: "C1.3", facet: "C1", poleA: "Energized. This is why I'm here.", poleB: "Drained. I'd rather be done." },
 84#QV:  { id: "C1.4", facet: "C1", poleA: "Sit with it and work it through.", poleB: "Find the quickest path to an answer." },
 85#WV:  { id: "C1.5", facet: "C1", poleA: "Pick up something mentally challenging.", poleB: "Do something that doesn't require much thought." },
 86#PH:  { id: "C1.6", facet: "C1", poleA: "Satisfied. That was a good use of time.", poleB: "Drained. I need to recover." },
 87#YM:  { id: "C1.7", facet: "C1", poleA: "I want to map it fully before acting.", poleB: "I want to get the gist and act." },
 88#BW:  { id: "C1.8", facet: "C1", poleA: "Engage fully — a good question pulls me back in.", poleB: "Give a brief answer — I'm done thinking for now." },
 89#JT:  // C2 — Override Tendency (8)
 90#TN:  { id: "C2.1", facet: "C2", poleA: "Slow down and verify it before trusting it.", poleB: "Trust it, then move on." },
 91#XK:  { id: "C2.2", facet: "C2", poleA: "Follow the analysis.", poleB: "Follow the gut, even if I can't justify it yet." },
 92#ZV:  { id: "C2.3", facet: "C2", poleA: "Don't fully trust it until I can.", poleB: "Trust it anyway. Some knowledge is pre-verbal." },
 93#KB:  { id: "C2.4", facet: "C2", poleA: "A hypothesis I then check.", poleB: "Something I trust and run with." },
 94#BQ:  { id: "C2.5", facet: "C2", poleA: "Try to verify it from another source.", poleB: "Accept it if the person seems credible." },
 95#JQ:  { id: "C2.6", facet: "C2", poleA: "I usually circle back and check it later.", poleB: "I trust it and move on." },
 96#KV:  { id: "C2.7", facet: "C2", poleA: "A signal to dig deeper.", poleB: "A drag I'd rather skip." },
 97#RS:  { id: "C2.8", facet: "C2", poleA: "I override instinct with analysis.", poleB: "I trust instinct and analyze after." },
 98#BQ:  // D1 — Entry Point (8)
 99#KZ:  { id: "D1.1", facet: "D1", poleA: "Break it into steps and solve each one.", poleB: "Get the overall shape of it, then fill in." },
100#QJ:  { id: "D1.2", facet: "D1", poleA: "Component by component, until the whole assembles.", poleB: "Whole first, then I learn what the parts are." },
101#VH:  { id: "D1.3", facet: "D1", poleA: "Line by line, in order.", poleB: "Around the page, grabbing the shape of it first." },
