120#NT:  C1: "Deliberation Preference", C2: "Override Tendency",
121#KB:  D1: "Entry Point", D2: "Decomposition Habit",
122#XB:};
123#TM:const AXIS_OF: Record<FacetId, AxisId> = { C1: "C", C2: "C", D1: "D", D2: "D" };
124#QH:const AXIS_NAMES: Record<AxisId, string> = { C: "Processing Mode", D: "Encoding Structure" };
125#ZR:// Quadrant order matching the build: C>50,D>50=Algorithm, C>50,D<50=Architecture,
126#MV:// C<50,D<50=Gestalt, C<50,D>50=Cipher.
127#KN:const QUADRANT_NAMES = ["Algorithm", "Architecture", "Gestalt", "Cipher"];
128#HS:const QUADRANT_ARCHETYPES = ["The Algorithm", "The Architecture", "The Gestalt", "The Cipher"];
129#PR:const TENSION_MARGIN = 20;
