131#XW:// facet → item indices (32-item bank)
132#SJ:const FACET_ITEMS: Record<FacetId, number[]> = {} as any;
133#QM:for (const f of FACETS) FACET_ITEMS[f] = [];
134#VW:ITEMS.forEach((item, i) => FACET_ITEMS[item.facet].push(i));
