136#NJ:// MMA-16: curated 4-per-facet subset
137#TH:const MMA16_IDS = new Set(["C1.1", "C1.4", "C1.6", "C1.8", "C2.1", "C2.2", "C2.5", "C2.7", "D1.1", "D1.4", "D1.5", "D1.6", "D2.2", "D2.5", "D2.7", "D2.8"]);
138#YN:const MMA16_INDICES = ITEMS.map((it, i) => MMA16_IDS.has(it.id) ? i : -1).filter(i => i >= 0);
139#YQ:const FACET_ITEMS_16: Record<FacetId, number[]> = {} as any;
140#MS:for (const f of FACETS) FACET_ITEMS_16[f] = FACET_ITEMS[f].filter(i => MMA16_IDS.has(ITEMS[i].id));
