142#WK:// ── HELPERS ────────────────────────────────────────────
143#PZ:function clamp(v: number, lo: number, hi: number): number {
144#WR:  return Math.max(lo, Math.min(hi, Math.round(v)));
145#WJ:}
146#JM:
147#YR:function gauss(mean: number, std: number): number {
148#XJ:  let u = 0, v = 0;
149#JW:  while (u === 0) u = Math.random();
150#MR:  while (v === 0) v = Math.random();
151#KX:  return mean + std * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
152#QT:}
153#VX:
154#BJ:function choice<T>(arr: T[]): T {
155#ZQ:  return arr[Math.floor(Math.random() * arr.length)];
156#PQ:}
