158#YN:// ── SCORING ENGINE (length-aware, same 13-step model) ─
159#SZ:function score(rawResponses: number[], orientations?: number[], activeIdxs?: number[]): ScoreResult {
160#QR:  const idxs = activeIdxs ?? ITEMS.map((_, i) => i);
161#WR:  if (rawResponses.length !== 32) throw new Error(`Need 32 responses (master bank), got ${rawResponses.length}`);
162#NY:  const ori = orientations ?? new Array(32).fill(1);
163#VQ:
164#PP:  // Normalize all 32 master-bank items (keeps r.normalized 32-length)
165#HV:  const normalized: number[] = [];
166#QQ:  for (let i = 0; i < 32; i++) {
167#WK:    normalized.push(ori[i] === 1 ? rawResponses[i] : 8 - rawResponses[i]);
168#SP:  }
169#KK:  // Per-facet bank indexes for active subset
170#TP:  const localFacetMap: Record<FacetId, number[]> = {} as any;
171#TQ:  for (const f of FACETS) localFacetMap[f] = (activeIdxs ? FACET_ITEMS_16 : FACET_ITEMS)[f];
172#VK:
173#NS:  // Facet scores (dynamic n)
174#NB:  const facets = {} as Record<FacetId, FacetResult>;
175#NB:  for (const facet of FACETS) {
176#NY:    const fIdxs = localFacetMap[facet];
177#PV:    const norms = fIdxs.map(i => normalized[i]);
178#QN:    const sum = norms.reduce((a, b) => a + b, 0);
179#RJ:    const n = fIdxs.length;
180#PJ:    const mean = sum / n;
181#SW:    const scoreVal = (mean - 1) / 6 * 100;
182#RH:    const variance = norms.reduce((a, x) => a + (x - mean) ** 2, 0) / n;
183#YP:    facets[facet] = { norms, sum, mean, score: scoreVal, variance };
184#ZZ:  }
185#HM:
186#ZB:  // Axis scores
187#SH:  const axis = {
188#TZ:    C: { score: (facets.C1.score + facets.C2.score) / 2 },
189#MJ:    D: { score: (facets.D1.score + facets.D2.score) / 2 },
190#RJ:  };
191#BH:
192#SK:  const c_off = axis.C.score - 50;
193#BB:  const d_off = axis.D.score - 50;
194#XY:  const MAX_DIST = Math.sqrt(50 * 50 + 50 * 50);
195#NR:  const distance = Math.sqrt(c_off * c_off + d_off * d_off);
196#KM:  const prototypicality = distance / MAX_DIST;
197#MH:
198#ZM:  const angle_rad = Math.atan2(d_off, c_off);
199#VH:  let angle_deg = angle_rad * 180 / Math.PI;
200#PK:  if (angle_deg < 0) angle_deg += 360;
201#PZ:
202#KH:  // Quadrant: C>50,D>50=Algorithm(0), C>50,D<50=Architecture(1),
203#YH:  //          C<50,D<50=Gestalt(2), C<50,D>50=Cipher(3)
204#MV:  let quadrant: number;
205#PZ:  if (c_off >= 0 && d_off >= 0) quadrant = 0;
206#WS:  else if (c_off >= 0 && d_off < 0) quadrant = 1;
207#VY:  else if (c_off < 0 && d_off < 0) quadrant = 2;
208#VZ:  else quadrant = 3;
209#ZK:
210#HH:  // Gradation
211#BV:  const QUAD_ENTRY_EDGE = [90, 0, 270, 180]; // Algorithm, Architecture, Gestalt, Cipher
212#MB:  const entry_edge = QUAD_ENTRY_EDGE[quadrant];
213#XN:  const progress = (entry_edge - angle_deg + 360) % 360;
214#BW:  if (progress > 90) {
215#VX:    throw new Error(`Gradation mapping error: ${QUADRANT_NAMES[quadrant]} angle ${angle_deg.toFixed(2)}° → progress ${progress.toFixed(2)}°`);
216#ZQ:  }
217#RJ:  const angle_in_quad = progress;
218#RS:  let gradation: string;
219#ZB:  if (progress < 30) gradation = "Early";
220#VN:  else if (progress < 60) gradation = "Mid";
221#NY:  else gradation = "Late";
222#KK:
223#VN:  // Tension + classification
224#JS:  const is_near_center = prototypicality < 0.28;
225#WQ:  const tension = {} as Record<AxisId, { s1: number; s2: number; tense: boolean }>;
226#TJ:  (["C", "D"] as AxisId[]).forEach(ax => {
227#PH:    const [f1, f2] = (ax === "C" ? ["C1", "C2"] : ["D1", "D2"]) as [FacetId, FacetId];
228#VM:    const s1 = facets[f1].score;
229#XR:    const s2 = facets[f2].score;
230#QJ:    const o1 = s1 - 50, o2 = s2 - 50;
231#HY:    const opposite = o1 * o2 < 0;
232#RP:    const strong = Math.abs(o1) >= TENSION_MARGIN && Math.abs(o2) >= TENSION_MARGIN;
233#HN:    tension[ax] = { s1, s2, tense: opposite && strong };
234#HP:  });
235#NZ:  const has_tension = tension.C.tense || tension.D.tense;
236#KK:  const is_threshold = is_near_center;
237#ZK:  const result_type: string = is_threshold ? "HaltingPoint" : QUADRANT_NAMES[quadrant];
238#NQ:
239#QB:  // Facet contribution (tension-aware)
240#BB:  const contrib: Record<AxisId, FacetContrib> = {} as any;
241#BZ:  for (const [ax, [f1, f2]] of [["C", ["C1", "C2"]] as [AxisId, [FacetId, FacetId]], ["D", ["D1", "D2"]] as [AxisId, [FacetId, FacetId]]]) {
242#VM:    const s1 = facets[f1].score;
243#XR:    const s2 = facets[f2].score;
244#PY:    const d1 = Math.abs(s1 - 50);
245#SN:    const d2 = Math.abs(s2 - 50);
246#ZR:    let dom: string;
247#PJ:    if (tension[ax].tense) dom = "tense";
248#JY:    else if (Math.abs(s1 - s2) < 0.01) dom = "equal";
249#ZN:    else dom = d1 > d2 ? f1 : f2;
250#YH:    contrib[ax] = { dominant: dom, s1, s2, d1, d2 };
251#KT:  }
252#TZ:
253#HY:  // Facet consistency
254#NT:  const facet_consistency = {} as Record<FacetId, number>;
255#YP:  for (const f of FACETS) facet_consistency[f] = Math.sqrt(facets[f].variance);
256#XK:
257#ZV:  return {
258#BZ:    name: "", raw: rawResponses, normalized,
259#XK:    facets, axis,
260#ZP:    c_off, d_off,
261#WY:    distance, prototypicality,
262#RS:    angle_deg, angle_in_quad,
263#SR:    quadrant, quadrant_name: QUADRANT_NAMES[quadrant],
264#YS:    gradation,
265#HH:    is_near_center, is_threshold, has_tension, result_type,
266#MN:    contrib, facet_consistency,
267#PN:    _orient: ori,
268#PP:  };
269#HR:}
