272#JM:function gen(name: string, c1_c: number, c2_c: number, d1_c: number, d2_c: number, noise = 1.0): [string, number[], number[]] {
273#SM:  const orient = new Array(32).fill(0).map(() => choice([1, -1]));
274#NM:  const centers: Record<FacetId, number> = { C1: c1_c, C2: c2_c, D1: d1_c, D2: d2_c };
275#KK:  const raw: number[] = [];
276#WY:  for (let i = 0; i < ITEMS.length; i++) {
277#SK:    const item = ITEMS[i];
278#SX:    const c = centers[item.facet];
279#HZ:    const trait = clamp(gauss(c, noise), 1, 7);
280#JW:    const r = orient[i] === 1 ? trait : (8 - trait);
281#YH:    raw.push(r);
282#VP:  }
283#NN:  return [name, raw, orient];
284#MV:}
